import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Quick Launch Settings","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/quick-launch.md","filePath":"user-guide/settings/quick-launch.md","lastUpdated":1788085660000}'),n={name:"user-guide/settings/quick-launch.md"};function r(l,e,o,c,h,u){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="quick-launch-settings" tabindex="-1">Quick Launch Settings <a class="header-anchor" href="#quick-launch-settings" aria-label="Permalink to &quot;Quick Launch Settings&quot;">​</a></h1><p>Quick Launch is the launch panel shown below the Quick Search Window when the search box is empty. It combines manually managed items with selected dynamic data sources such as Favorites and History.</p><h2 id="_1-master-switch" tabindex="-1">1. Master switch <a class="header-anchor" href="#_1-master-switch" aria-label="Permalink to &quot;1. Master switch&quot;">​</a></h2><ul><li><strong>Enable quick launch panel</strong>: Enables the panel. It appears only in the Quick Search Window when the query is empty and at least one source has available data.</li><li>When disabled, no source is loaded for the panel.</li><li>The panel height is based on the source with the most items and is capped by the Quick Search Window&#39;s maximum result area.</li></ul><h2 id="_2-manual-quick-launch-items" tabindex="-1">2. Manual quick-launch items <a class="header-anchor" href="#_2-manual-quick-launch-items" aria-label="Permalink to &quot;2. Manual quick-launch items&quot;">​</a></h2><p>Open <strong>Settings → Quick Launch → Quick Launch</strong> to manage your own items:</p><ul><li>Add a file, folder, URL, or Windows shell path. Environment variables are supported when the target is checked.</li><li>The display name is optional. If it is blank, Lertaro derives a name from the target.</li><li>The file and folder browse buttons support selecting multiple items at once; each valid, non-duplicate target is added as its own entry.</li><li>Use the drag handle to reorder items. Editing changes the same row into an inline editor with save and cancel controls; the remove control deletes the item.</li><li>Missing targets are omitted from the panel until they become available again.</li></ul><h2 id="_3-data-sources" tabindex="-1">3. Data sources <a class="header-anchor" href="#_3-data-sources" aria-label="Permalink to &quot;3. Data sources&quot;">​</a></h2><p>Open <strong>Settings → Quick Launch → Data sources</strong> to choose dynamic sources:</p><ul><li>Sources come from the installed Quick Panel tab providers. This lets Quick Launch reuse Favorites, History, Windows History, Last Directory, Recent Files, and future plugin sources without maintaining a second copy of their data.</li><li>A source is enabled by default when its provider is present. Only explicitly disabled providers are stored in user settings.</li><li>A source gets a panel tab only when it is enabled and currently returns data. Empty sources are hidden.</li><li>If all manual items and dynamic sources are empty, the Quick Launch panel is hidden.</li></ul><h2 id="_4-panel-interaction" tabindex="-1">4. Panel interaction <a class="header-anchor" href="#_4-panel-interaction" aria-label="Permalink to &quot;4. Panel interaction&quot;">​</a></h2><ul><li>The number of columns adapts to the search-bar width.</li><li>With one source, the source indicator is hidden.</li><li>With multiple sources, the bottom strip shows one dot per source. The selected dot is blue and the other dots are gray; hovering over a dot expands it to show the source name.</li><li>Hold <strong>Shift</strong> and scroll over the panel to cycle through sources. The selected source briefly plays the same reveal animation.</li><li>Starting a query hides the panel.</li></ul>',12)])])}const p=a(n,[["render",r]]);export{m as __pageData,p as default};
